async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  let pending = "";
  let line = 1;
  let delivered = 0;

  async function processLine(text) {
    if (text.trim().length === 0) return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${line}`);
      error.code = "BAD_LINE";
      error.line = line;
      throw error;
    }

    delivered++;
    return (await deliver(value, line)) !== false;
  }

  try {
    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        pending += decoder.decode();

        if (pending.length !== 0) {
          await processLine(pending);
        }
        return delivered;
      }

      const text = decoder.decode(chunk, { stream: true });
      let start = 0;

      for (let i = 0; i < text.length; i++) {
        if (text.charCodeAt(i) !== 10) continue;

        const current = pending + text.slice(start, i);
        pending = "";

        if (!(await processLine(current))) {
          return delivered;
        }

        line++;
        start = i + 1;
      }

      pending += text.slice(start);
    }
  } finally {
    await input.close();
  }
}
